const ctx = $input.first().json;
const intent = ($('Workflow Input').first().json.intent) || 'answering';

function out(o) {
  return [{ json: Object.assign({ ok: true, action: '', slot_key: '', variant: '', question_text: '', goal: '', choices_json: '[]', chosen_slot_utc: '' }, o) }];
}

const defs = Array.isArray(ctx.slot_definitions) ? ctx.slot_definitions : [];
if (defs.length === 0) {
  return [{ json: { ok: false, error: 'no_slot_definitions', action: '', slot_key: '', variant: '', question_text: '', goal: '', choices_json: '[]', chosen_slot_utc: '' } }];
}

const th = ctx.thresholds || {};
const maxAttempts = typeof th.slot_max_attempts === 'number' ? th.slot_max_attempts : 2;
const maxQuestions = typeof th.max_questions === 'number' ? th.max_questions : 8;
// How many times the bot may put a list of times in front of one lead. A third
// identical slot list is how it used to tell a lead it was stuck.
const maxOffers = typeof th.max_booking_offers === 'number' ? th.max_booking_offers : 2;
const nurtureMaxBudget = typeof th.nurture_max_budget === 'number' ? th.nurture_max_budget : 0;
const nurturePurposes = Array.isArray(th.nurture_purposes) ? th.nurture_purposes : [];

const lines = ctx.lines || {};
const leadName = String(ctx.lead_full_name || '').trim();
function line(key) {
  const l = lines[key];
  if (!l || typeof l !== 'object') return '';
  return String(l[ctx.language] || l.en || '').trim();
}

const qual = {};
for (const q of (Array.isArray(ctx.qualification) ? ctx.qualification : [])) { qual[q.slot_key] = q; }
const stateOf = function (k) { return qual[k] ? qual[k].state : 'empty'; };
const valueOf = function (k) { return qual[k] ? qual[k].value : null; };
const attemptsOf = function (k) { return qual[k] ? (qual[k].attempts || 0) : 0; };

const offersMade = Number(ctx.offers_made || 0);
const declines = Number(ctx.declines || 0);
const outboundSinceOffer = Number(ctx.outbound_since_offer || 0);

function comparable(v) {
  if (v && typeof v === 'object' && !Array.isArray(v) && (typeof v.min === 'number' || typeof v.max === 'number')) {
    return typeof v.min === 'number' ? v.min : 0;
  }
  return v;
}

function conditionSatisfied(cond) {
  if (!cond) return true;
  const st = stateOf(cond.slot);
  const known = (st === 'filled' || st === 'conflicted');
  // empty/filled ask about presence, so they must be answered before the
  // value comparisons below bail out on an unfilled slot.
  if (cond.op === 'empty') return !known;
  if (cond.op === 'filled') return known;
  if (!known) return false;
  const v = comparable(valueOf(cond.slot));
  const target = cond.value;
  if (cond.op === 'eq') return String(v) === String(target);
  if (cond.op === 'neq') return String(v) !== String(target);
  if (cond.op === 'gte') return Number(v) >= Number(target);
  if (cond.op === 'lte') return Number(v) <= Number(target);
  if (cond.op === 'in') return Array.isArray(target) && target.map(String).indexOf(String(v)) !== -1;
  return false;
}

const applicable = defs.filter(function (d) { return conditionSatisfied(d.condition); });
applicable.sort(function (a, b) { return a.priority - b.priority; });

function fmtMoney(n, cur) {
  const c = cur || ctx.currency || 'AED';
  if (n >= 1000000) return (Math.round((n / 1000000) * 10) / 10) + 'M ' + c;
  if (n >= 1000) return (Math.round(n / 1000)) + 'K ' + c;
  return n + ' ' + c;
}

function renderValue(v) {
  if (v === null || v === undefined) return '';
  if (typeof v === 'object' && !Array.isArray(v)) {
    if (typeof v.min === 'number' || typeof v.max === 'number') {
      if (typeof v.stated_text === 'string' && v.stated_text) return v.stated_text;
      if (typeof v.min === 'number' && typeof v.max === 'number') return fmtMoney(v.min, v.currency) + ' to ' + fmtMoney(v.max, v.currency);
      if (typeof v.max === 'number') return 'up to ' + fmtMoney(v.max, v.currency);
      return 'from ' + fmtMoney(v.min, v.currency);
    }
    const bits = [];
    if (v.full_name) bits.push(v.full_name);
    if (v.phone) bits.push(v.phone);
    if (v.email) bits.push(v.email);
    if (bits.length) return bits.join(', ');
    return JSON.stringify(v);
  }
  return String(v);
}

function askSlot(def) {
  const attempts = attemptsOf(def.slot_key);
  const choices = Array.isArray(def.question_choices) ? def.question_choices : [];
  const useChoices = attempts >= 1 && choices.length > 0;
  const variant = useChoices ? 'choices' : 'open';
  // question_open is now only the fallback wording, used when the composer
  // fails. question_goal is what the composer actually works from, so it can
  // write a sentence that fits the conversation instead of reciting a seed
  // string written for a lead who arrived talking about a project.
  let text = def.question_open;
  let goal = String(def.question_goal || def.question_open || '');
  if (def.slot_key === 'contact' && leadName) {
    const alt = line('contact_phone_only_line');
    if (alt) text = alt;
    goal = goal + ' - they have already given their name as ' + leadName + ', so never ask for it';
  }
  return out({ action: 'ask_slot', slot_key: def.slot_key, variant: variant, question_text: text, goal: goal, choices_json: JSON.stringify(useChoices ? choices : []) });
}

function declineOut(variant, goal, fallback) {
  return out({ action: 'acknowledge_decline', variant: variant, goal: goal, question_text: fallback || line('decline_ack_line') });
}

// One place decides whether the bot may put times in front of the lead again.
// Before this, every path that ran out of questions offered a meeting, so a
// lead who had just said no was offered one again on the very next turn.
function offerBooking(variant) {
  if (intent === 'booking_intent') {
    return out({ action: 'offer_booking', variant: variant, goal: 'they have asked about meeting the agent; offer the times listed and ask which one suits them' });
  }
  if (declines >= 1 || offersMade >= maxOffers) {
    return declineOut('holding', 'they have already turned a meeting down, so never raise one again; just make clear you are here for any questions about the projects', line('declined_twice_line'));
  }
  return out({ action: 'offer_booking', variant: variant, goal: 'offer the times listed and ask which one suits them' });
}

// Character classes rather than escapes: this source is round-tripped through
// JSON on every edit and a backslash does not always survive it.
const LABEL_RE = /^([a-z]{3})[ ]+([0-9]{1,2})[ ]+([a-z]{3}),?[ ]*([0-9]{1,2}):([0-9]{2})[ ]*(am|pm)/;

function normalise(rawText) {
  return ' ' + String(rawText || '')
    .toLowerCase()
    .replace(/['’]/g, '')
    // "31st" has to become "31" before the split, or the day number never matches.
    .replace(/([0-9])(st|nd|rd|th)(?![a-z])/g, '$1')
    .replace(/[^a-z0-9:]+/g, ' ') + ' ';
}

// A lead who is saying no is not picking a slot, whatever else is in the
// sentence. "I dont want a meeting yet first give me information" booked a
// meeting because "first" scored as slot number one.
const REFUSALS = ['no', 'not', 'nope', 'nah', 'dont', 'doesnt', 'didnt', 'cant', 'cannot', 'wont', 'wouldnt', 'never', 'later', 'skip', 'busy', 'unavailable'];

function looksLikeRefusal(text) {
  for (let i = 0; i < REFUSALS.length; i++) {
    if (text.indexOf(' ' + REFUSALS[i] + ' ') !== -1) return true;
  }
  return false;
}

function matchOfferedSlot(offered, rawText) {
  const text = normalise(rawText);
  if (looksLikeRefusal(text)) return null;

  const has = function (w) { return !!w && text.indexOf(' ' + w + ' ') !== -1; };
  const wordCount = text.trim().split(' ').filter(Boolean).length;
  const shortMessage = wordCount <= 5;

  const dayFull = { mon: 'monday', tue: 'tuesday', wed: 'wednesday', thu: 'thursday', fri: 'friday', sat: 'saturday', sun: 'sunday' };
  const ordinalDigit = [['1'], ['2'], ['3']];
  const ordinalWord = [['first', 'one'], ['second', 'two'], ['third', 'three']];

  let best = null;
  let bestScore = 0;
  let tied = false;

  for (let i = 0; i < offered.length; i++) {
    const label = String(offered[i].label_local || '').toLowerCase();
    let score = 0;

    if (i < 3) {
      let digit = false;
      for (const t of ordinalDigit[i]) { if (has(t)) { digit = true; break; } }
      let word = false;
      for (const t of ordinalWord[i]) { if (has(t)) { word = true; break; } }
      // A digit outranks a day number so a bare "1" still picks slot one even
      // when another slot falls on the 1st. A bare ordinal WORD only counts as
      // a pick in a short, choice-like message; inside a sentence it is prose.
      if (digit) score += 4;
      else if (word) score += (shortMessage ? 3 : 1);
    }

    const m = label.match(LABEL_RE);
    if (m) {
      const wdShort = m[1];
      const dayNum = m[2];
      const monShort = m[3];
      const hour = m[4];
      const mins = m[5];
      const mer = m[6];
      if (has(wdShort) || has(dayFull[wdShort])) score += 3;
      if (has(dayNum)) score += 3;
      if (has(monShort)) score += 1;
      if (has(hour + mer) || has(hour + ':' + mins) || has(hour)) score += 1;
    }

    if (score > bestScore) { bestScore = score; best = offered[i]; tied = false; }
    else if (score > 0 && score === bestScore) { tied = true; }
  }

  // Threshold raised from 2 to 3: one weak signal on its own must never book.
  if (best && bestScore >= 3 && !tied) return best;
  return null;
}

const booking = ctx.latest_booking || null;
const awaitingChoice = !!(booking && booking.status === 'offered');

if (ctx.conversation_status === 'booked') {
  // A booked lead saying no is asking to cancel, which the bot may not do. The
  // unknown action falls through Route Action to cannot_decide and a human
  // picks it up.
  if (intent === 'decline_booking') {
    return out({ action: 'cancel_request', variant: 'booked_then_declined' });
  }
  return out({ action: 'confirm_booking', variant: 'already_booked', goal: 'they are already booked for the time given; remind them of it and let them know nothing else is needed from them' });
}

// A refusal is answered before anything else. Nothing in the ladder could hear
// "no": the message fell through to reoffer_booking and the same three times
// went out again, with nothing to stop it.
if (intent === 'decline_booking') {
  if (declines >= 1) {
    return declineOut('declined_again', 'they have turned a meeting down more than once; accept it for good, never raise a meeting again, and make clear you are still here for questions about the projects', line('declined_twice_line'));
  }
  return declineOut('first_decline', 'they do not want a meeting right now; accept that without pushing back, and invite them to ask anything they want about the projects', line('decline_ack_line'));
}

const conflicted = applicable.filter(function (d) { return stateOf(d.slot_key) === 'conflicted'; });
if (conflicted.length > 0) {
  const d = conflicted[0];
  const q = qual[d.slot_key];
  const prev = Array.isArray(q.previous_values) ? q.previous_values : [];
  const oldV = prev.length ? prev[prev.length - 1] : null;
  const choices = [
    { label: renderValue(oldV), value: oldV },
    { label: renderValue(q.value), value: q.value }
  ];
  return out({
    action: 'resolve_conflict',
    slot_key: d.slot_key,
    variant: 'conflict',
    question_text: 'I have two different answers for this. Which one should I go with?',
    goal: 'you have two different answers on file for ' + d.slot_key + '; say so plainly and ask which of the two is right',
    choices_json: JSON.stringify(choices)
  });
}

if (awaitingChoice) {
  const offered = Array.isArray(booking.offered_slots) ? booking.offered_slots : [];
  const chosen = matchOfferedSlot(offered, ctx.last_inbound_text);
  if (chosen) {
    return out({ action: 'confirm_booking', variant: 'lead_picked', chosen_slot_utc: String(chosen.starts_at_utc || ''), goal: 'their meeting is now booked for the time given; confirm it and tell them the agent already has everything they have said' });
  }
}

if (intent === 'booking_intent' && !awaitingChoice) {
  return offerBooking('lead_asked');
}

if (!awaitingChoice) {
  const tier1 = applicable.filter(function (d) { return d.tier === 1 && d.required === true; });
  const tier1Pending = tier1.filter(function (d) {
    const st = stateOf(d.slot_key);
    return (st === 'empty' || st === 'unanswered') && attemptsOf(d.slot_key) < maxAttempts;
  });
  if (tier1Pending.length > 0) {
    return askSlot(tier1Pending[0]);
  }

  const budget = valueOf('budget');
  const timeline = valueOf('timeline');
  const purpose = valueOf('purpose');
  const budgetMax = (budget && typeof budget === 'object' && typeof budget.max === 'number') ? budget.max : null;
  const failsNurture = (budgetMax !== null && budgetMax < nurtureMaxBudget) || (String(timeline) === 'exploring') || (purpose !== null && nurturePurposes.indexOf(String(purpose)) !== -1);
  if (failsNurture) {
    return out({ action: 'nurture', variant: 'below_bar', goal: 'close the conversation warmly, with no meeting, and leave the door open for future launches' });
  }

  if ((ctx.questions_asked || 0) < maxQuestions) {
    const deeper = applicable.filter(function (d) {
      return d.tier > 1 && stateOf(d.slot_key) === 'empty' && attemptsOf(d.slot_key) < maxAttempts;
    });
    if (deeper.length > 0) {
      return askSlot(deeper[0]);
    }
  }
}

if (awaitingChoice) {
  // Two slot lists is the limit. Past that the bot stops asking and stays
  // useful instead - the old code returned reoffer_booking here forever.
  if (outboundSinceOffer >= maxOffers) {
    return declineOut('offers_exhausted', 'they have been shown the times and have not picked one; stop asking about a meeting and make clear you are happy to answer questions about the projects instead', line('decline_ack_line'));
  }
  return out({ action: 'reoffer_booking', variant: 'awaiting_choice', goal: 'they have not picked a time yet; put the same times back in front of them, worded differently from last time' });
}

return offerBooking('qualified');
